scwin.loadChatModuleInTab = async function (tabContentElement, moduleInfo) {
    if (!tabContentElement) {
        console.error("탭 콘텐츠 요소가 없습니다.");
        return;
    }

    try {
        console.log("탭에 ChatModule 로드 시작...");

        // ChatModule 동적 로드 (session_room.xml 방식과 동일)
        let ChatModule = await window.App.loadModule(
            "/InsWebApp/media/dist/modules/chat.bundle.js",
            "ChatModule"
        );

        if (ChatModule && !ChatModule.prototype) {
            ChatModule = ChatModule.ChatModule || ChatModule.default;
        }

        // 탭 콘텐츠 영역을 채팅 컨테이너로 설정
        tabContentElement.style.cssText = `
            width: 100%;
            height: 100%;
            background: white;
            position: relative;
        `;

        // ChatModule 인스턴스 생성
        var chatModule = new ChatModule(tabContentElement, {
            roomId: scwin.currentSessionId || "default-room",
            currentUser: "사용자" + Math.floor(Math.random() * 1000), // -> 채팅 사용자아이디 랜덤값
            websocketManagerUrl: "/InsWebApp/js/websocket/websocket-manager.js"
        });

        // 이벤트 리스너 등록
        chatModule.on('ready', () => {
            console.log("✅ 탭 ChatModule 준비 완료!");

            // 환영 메시지 추가
            // setTimeout(() => {
            //     chatModule.addMessage("system", "채팅방에 입장했습니다!", "시스템");
            // }, 500);
        });

        chatModule.on('messageSent', (data) => {
            console.log("메시지 전송됨:", data);
        });

        chatModule.on('messageReceived', (data) => {
            console.log("메시지 수신됨:", data);
        });

        chatModule.on('error', (error) => {
            console.error("❌ 탭 ChatModule 오류:", error);
        });

        console.log("✅ 탭에 ChatModule 로드 완료!");

    } catch (error) {
        console.error("❌ 탭에 ChatModule 로드 실패:", error);

        // 실패 시 기본 UI 표시
        tabContentElement.innerHTML = `
            <div style="padding: 20px; text-align: center; color: #666;">
                <div style="font-size: 1.1rem; font-weight: 600; margin-bottom: 5px;">채팅</div>
                <div style="font-size: 0.9rem; color: #999;">모듈 로드 중 오류 발생</div>
                <div style="font-size: 0.8rem; color: #f44336; margin-top: 10px;">${error.message}</div>
            </div>
        `;
    }
};

