// 탭용 참여자 목록 모듈 로더
scwin.loadParticipantsModuleInTab = function (tabContentElement, moduleInfo) {
    console.log("탭에 참여자 목록 모듈 로드:", moduleInfo);

    // 참여자 목록 UI 생성
    tabContentElement.innerHTML = `
    `;

    // 버튼 이벤트 추가
    var buttons = tabContentElement.querySelectorAll('button');
    buttons.forEach(function (button) {
        button.addEventListener('click', function (e) {
            e.preventDefault();
            // 버튼 클릭 효과
            var originalBg = this.style.backgroundColor;
            this.style.backgroundColor = '#ddd';
            setTimeout(() => {
                this.style.backgroundColor = originalBg;
            }, 150);
        });
